import {
  storageAdmin,
  testCaseStorage,
  benchmarkStorage,
  runStorage,
  analyticsStorage,
  opensearchStorage,
  StorageTestCase,
  StorageBenchmark,
  StorageRun,
  StorageAnalyticsRecord,
} from '@/services/storage/opensearchClient';

// Mock the config
jest.mock('@/lib/config', () => ({
  ENV_CONFIG: {
    storageApiUrl: 'http://localhost:4001/api/storage',
  },
}));

// Mock global fetch
const mockFetch = jest.fn();
global.fetch = mockFetch;

describe('OpenSearch Storage Client', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  // ==================== Helper Functions ====================

