    it('still accepts a valid body (201)', async () => {
      if (!backendAvailable) return;
      const response = await fetch(`${BASE_URL}/api/storage/test-cases`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: `${NAME_MARKER}-tc-valid`,
